import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, DirectionalLight, Color } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Backdrop plane (card background) ---
  const backdropGeo = new PlaneGeometry(1.6, 1.6);
  const backdropMat = new MeshBasicNodeMaterial({
    color: new Color('#0b0b10'),
    side: 2, // DoubleSide
  });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -0.1;
  group.add(backdrop);

  // --- Load GLB mesh ---
  let glbScene = null;
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    glbScene = gltf.scene;
    group.add(glbScene);
    // Ensure the mesh is centered and scaled appropriately
    glbScene.position.set(0, 0, 0);
    // The GLB may have its own materials; we don't override
  });

  // --- Accent rim light ---
  const rimLight = new DirectionalLight(new Color('#ff2a38'), 0.8);
  rimLight.position.set(1, 0.5, -2);
  group.add(rimLight);

  // --- Weighted-settle entrance ---
  const entranceTimeline = gsap.timeline({ paused: true });
  entranceTimeline.fromTo(group.scale, { x: 1.04, y: 1.04, z: 1.04 }, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  entranceTimeline.play();

  // --- Hover rise-in animation ---
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(group.position, {
    y: 0.15,
    duration: 0.3,
    ease: 'power3.out',
  });

  // --- Cinematic primitives ---
  const primitiveCleanups = [];
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      const result = ctx.primitives[prim.name](group, prim.params);
      if (result && result.cleanup) {
        primitiveCleanups.push(result.cleanup);
      }
    }
  }

  // --- Event handlers ---
  group.userData.handlers = {
    pointerover: () => {
      hoverTimeline.play();
    },
    pointerout: () => {
      hoverTimeline.reverse();
    },
    pointerdown: (event) => {
      // Simple click detection: store pointerdown time and position
      group.userData._pointerDown = { time: performance.now(), x: event.clientX, y: event.clientY };
    },
    pointerup: (event) => {
      const down = group.userData._pointerDown;
      if (down) {
        const dt = performance.now() - down.time;
        const dx = event.clientX - down.x;
        const dy = event.clientY - down.y;
        if (dt < 300 && Math.abs(dx) < 10 && Math.abs(dy) < 10) {
          ctx.emit('hub-features.select', {});
        }
        delete group.userData._pointerDown;
      }
    },
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    entranceTimeline.kill();
    hoverTimeline.kill();
    primitiveCleanups.forEach(fn => fn());
    // Dispose geometry and material
    backdropGeo.dispose();
    backdropMat.dispose();
    // If GLB scene is loaded, dispose its resources
    if (glbScene) {
      glbScene.traverse((child) => {
        if (child.isMesh) {
          child.geometry.dispose();
          if (Array.isArray(child.material)) {
            child.material.forEach(m => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      });
    }
  };

  return group;
}
